import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Bfn7EBcS.js";const u=JSON.parse('{"title":"Physical devices","description":"","frontmatter":{},"headers":[],"relativePath":"guide/physical-devices.md","filePath":"guide/physical-devices.md","lastUpdated":1795740873000}'),i={name:"guide/physical-devices.md"};function r(h,e,n,d,c,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="physical-devices" tabindex="-1">Physical devices <a class="header-anchor" href="#physical-devices" aria-label="Permalink to &quot;Physical devices&quot;">​</a></h1><p>Beholder can capture from a physical Android phone connected over adb. Enable USB debugging, plug the phone in, accept the prompt, and pick it under <strong>devices</strong> in the target menu.</p><h2 id="how-the-traffic-travels" tabindex="-1">How the traffic travels <a class="header-anchor" href="#how-the-traffic-travels" aria-label="Permalink to &quot;How the traffic travels&quot;">​</a></h2><ul><li>Beholder runs <code>adb reverse tcp:&lt;port&gt; tcp:&lt;port&gt;</code> and sets the phone&#39;s global HTTP proxy to <code>127.0.0.1:&lt;port&gt;</code>.</li><li>The reverse rule is lost when the phone disconnects, so Beholder re-issues it every two seconds while capturing.</li><li>The proxy that was set before the capture is saved and restored when you stop, quit, or run the cleanup. If the phone is unplugged at that moment, the saved value is restored the next time Beholder sees it.</li><li>The proxy only listens on your Mac&#39;s loopback interface. Nothing is exposed to the network.</li></ul><h2 id="what-you-can-inspect" tabindex="-1">What you can inspect <a class="header-anchor" href="#what-you-can-inspect" aria-label="Permalink to &quot;What you can inspect&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phone</th><th>HTTPS</th><th>Other features</th></tr></thead><tbody><tr><td>Without root</td><td>Only apps that trust user certificates</td><td>Logcat, shell, APK install, plain HTTP, databases of debuggable apps</td></tr><tr><td>With Magisk</td><td>Apps without certificate pinning</td><td>The above, plus the database viewer</td></tr></tbody></table><h2 id="magisk" tabindex="-1">Magisk <a class="header-anchor" href="#magisk" aria-label="Permalink to &quot;Magisk&quot;">​</a></h2><p>When <code>su</code> works from the adb shell, <strong>Unlock</strong> in the device setup mounts the Beholder certificate over the system store. Allow Shell in the Magisk Superuser tab if the request is denied. The mount disappears on reboot, and the cleanup removes it. Restart the app you want to inspect so it picks up the certificate.</p><h2 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to &quot;Databases&quot;">​</a></h2><p>When <code>adb root</code> is not available, the database viewer reads through <code>su</code> on Magisk phones, or through <code>run-as</code> for debuggable apps. The <code>-wal</code> and <code>-shm</code> files are copied together with the database. Some manufacturers disable <code>run-as</code>. Writing changes back to a phone still needs <code>adb root</code>.</p><h2 id="capture-one-app" tabindex="-1">Capture one app <a class="header-anchor" href="#capture-one-app" aria-label="Permalink to &quot;Capture one app&quot;">​</a></h2><p>With the <a href="https://github.com/JavierGaMa/BeholdersApk/releases" target="_blank" rel="noreferrer">Beholder companion app</a> 0.3.0 or newer installed, pick an app under <strong>Capture one app</strong> in the device setup. The companion runs a local VPN scoped to that app and points it at the proxy on your Mac, so the rest of the phone is left alone and the global proxy is not touched. The phone may ask you to accept the VPN once. The app still has to trust the certificate and honor the system proxy.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Without the companion, the global proxy affects the whole phone. Apps that do not trust the certificate fail their HTTPS requests while capturing; hosts in <code>tls_bypass_hosts</code> in <code>config.toml</code> are relayed untouched.</li><li>Clients that ignore the system proxy or pin certificates are not captured.</li><li>iPhones are not supported.</li></ul>',14)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
